export const ISO_CSS = "/*\n * Styles for the isometric drawing kit (src/lib/iso.tsx). Colours come from the page's own role\n * tokens, so every drawing follows the palette and the theme without a second set of values.\n */\n\n.iso-scene {\n  --i-line: var(--iso-line, var(--color-text));\n  --i-paper-1: var(--color-bg-surface);\n  --i-paper-2: var(--color-bg-inset);\n  --i-paper-3: var(--color-border);\n  --i-accent-1: var(--cobalt-400);\n  --i-accent-2: var(--color-accent-solid);\n  --i-accent-3: var(--cobalt-800);\n  --i-shadow: var(--iso-shadow, var(--color-accent-wash));\n  display: block;\n  width: 100%;\n  height: auto;\n  overflow: visible;\n}\n\n.iso-box polygon,\n.iso-face rect,\n.iso-face circle,\n.iso-face line,\n.iso-face path {\n  stroke: var(--i-line);\n  stroke-width: 1.5;\n  stroke-linejoin: round;\n  stroke-linecap: round;\n  vector-effect: none;\n}\n\n.tone-paper > .f-top {\n  fill: var(--i-paper-1);\n}\n.tone-paper > .f-left {\n  fill: var(--i-paper-2);\n}\n.tone-paper > .f-right {\n  fill: var(--i-paper-3);\n}\n\n.tone-accent > .f-top {\n  fill: var(--i-accent-1);\n}\n.tone-accent > .f-left {\n  fill: var(--i-accent-2);\n}\n.tone-accent > .f-right {\n  fill: var(--i-accent-3);\n}\n\n.tone-ink > .f-top {\n  fill: var(--i-ink-top);\n}\n.tone-ink > .f-left {\n  fill: var(--i-ink-left);\n}\n.tone-ink > .f-right {\n  fill: var(--i-ink-right);\n}\n\n.tone-ghost > polygon {\n  fill: transparent;\n  stroke-dasharray: 4 4;\n  stroke-width: 1.25;\n}\n\n.iso-shadow {\n  fill: var(--i-shadow);\n}\n\n.iso-guide {\n  stroke: var(--i-line);\n  stroke-width: 1.25;\n  stroke-dasharray: 2 6;\n  stroke-linecap: round;\n  opacity: 0.45;\n}\n\n/* artwork drawn on faces */\n.iso-face .iso-panel {\n  fill: var(--i-accent-1);\n  stroke-width: 1.25;\n}\n.obj-cabinet .f-right ~ .iso-face:last-of-type .iso-panel,\n.iso-face .iso-panel.is-side {\n  fill: transparent;\n  opacity: 0.55;\n}\n.iso-face .iso-plate {\n  fill: var(--i-paper-1);\n  stroke-width: 1;\n}\n.iso-face .iso-pull {\n  fill: var(--i-paper-1);\n  stroke-width: 1;\n}\n.iso-face .iso-slot,\n.iso-face .iso-well {\n  fill: var(--i-line);\n  stroke: none;\n}\n.iso-face .iso-well {\n  fill: var(--i-paper-1);\n  stroke: var(--i-line);\n  stroke-width: 1;\n}\n.iso-tiny {\n  font-family: var(--font);\n  font-size: 7.4px;\n  font-weight: 650;\n  letter-spacing: 0.01em;\n  fill: var(--i-line);\n  stroke: none;\n  text-rendering: geometricPrecision;\n}\n.iso-face .iso-detail,\n.iso-face .iso-detail-box {\n  stroke-width: 1;\n  opacity: 0.55;\n  fill: none;\n}\n.iso-face .iso-chrome {\n  fill: var(--i-paper-3);\n  stroke-width: 1;\n}\n.iso-face .iso-dot {\n  fill: var(--i-paper-1);\n  stroke-width: 0.8;\n}\n.iso-face .iso-bubble {\n  fill: var(--i-paper-3);\n  stroke-width: 1;\n}\n.iso-face .iso-bubble.is-accent {\n  fill: var(--i-accent-2);\n}\n.iso-face .iso-screen {\n  fill: var(--i-ink-left);\n  stroke-width: 1;\n}\n.iso-face .iso-prompt,\n.iso-face .iso-termline {\n  fill: none;\n  stroke: var(--i-on-ink);\n  stroke-width: 1.6;\n}\n.iso-face .iso-termline.is-dim {\n  opacity: 0.45;\n}\n.iso-face .iso-termline.is-accent {\n  stroke: var(--i-accent-1);\n}\n.iso-face .iso-vent {\n  stroke: var(--i-on-ink);\n  stroke-width: 1.4;\n  opacity: 0.5;\n}\n.iso-face .iso-vent-box {\n  fill: none;\n  stroke: var(--i-on-ink);\n  stroke-width: 1.2;\n  opacity: 0.5;\n}\n.iso-face .iso-light {\n  fill: var(--i-accent-1);\n  stroke: var(--i-on-ink);\n  stroke-width: 1;\n}\n\n/* labels */\n.iso-pill rect {\n  fill: var(--i-paper-1);\n  stroke: var(--i-line);\n  stroke-width: 1.5;\n}\n.iso-pill text {\n  font-family: var(--font);\n  font-size: 13px;\n  font-weight: 600;\n  letter-spacing: -0.01em;\n  fill: var(--i-line);\n  text-rendering: geometricPrecision;\n}\n.iso-pill .iso-leader {\n  stroke: var(--i-line);\n  stroke-width: 1.5;\n}\n.iso-pill-icon path {\n  fill: var(--i-line);\n}\n\n.iso-pill.is-solid rect {\n  fill: var(--i-accent-2);\n}\n.iso-pill.is-solid text {\n  fill: var(--color-on-accent);\n}\n\n/* tracks, slots and the gap a drawer leaves */\n.iso-track {\n  fill: none;\n  stroke: var(--i-line);\n  stroke-width: 1.25;\n  stroke-dasharray: 2 6;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n  opacity: 0.4;\n}\n.iso-face .iso-slot {\n  fill: var(--i-ink-left);\n  stroke: var(--i-line);\n  stroke-width: 1;\n}\n.iso-face .iso-slot-lip {\n  stroke: var(--i-on-ink);\n  stroke-width: 0.8;\n  opacity: 0.35;\n}\n.iso-face .iso-gap {\n  fill: var(--i-accent-3);\n  stroke: none;\n}\n\n/* motion: cards, tracks and drawers run on SVG timelines (see SceneMotion); a light blinks */\n.iso-face .iso-light {\n  animation: iso-blink 2.4s steps(2, jump-none) infinite;\n}\n\n@keyframes iso-blink {\n  50% {\n    fill: var(--i-ink-left);\n  }\n}\n\n.iso-termline.is-accent {\n  stroke-dasharray: 60;\n  animation: iso-type 3.2s steps(8, end) infinite;\n}\n\n@keyframes iso-type {\n  0% {\n    stroke-dashoffset: 60;\n  }\n  45%,\n  100% {\n    stroke-dashoffset: 0;\n  }\n}\n\n/* scenes only move while they are on screen */\n[data-inview=\"false\"] .iso-light,\n[data-inview=\"false\"] .iso-termline {\n  animation-play-state: paused;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .iso-face .iso-light,\n  .iso-termline.is-accent {\n    animation: none;\n  }\n}\n";
